### Method 1: Using `Column` and `Row`

This method involves nesting `Row` widgets inside a `Column` widget, where each `Row` represents one row of items.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: Text('Limit Items Per Row'),
        ),
        body: LimitedItemsPerRow(),
      ),
    );
  }
}

class LimitedItemsPerRow extends StatelessWidget {
  final int itemsPerRow = 3; // Number of items per row

  @override
  Widget build(BuildContext context) {
    return Column(
      children: List.generate(10, (index) {
        if (index % itemsPerRow == 0) {
          // Start a new row every `itemsPerRow` items
          return Padding(
            padding: const EdgeInsets.all(8.0),
            child: Row(
              children: List.generate(itemsPerRow, (rowIndex) {
                if (index + rowIndex < 10) {
                  return Container(
                    width: 100,
                    height: 100,
                    color: Colors.blue[100 * (index + rowIndex)],
                    child: Center(child: Text((index + rowIndex).toString())),
                  );
                }
                return SizedBox.shrink(); // Return an empty space if no item is needed
              }),
            ),
          );
        }
        return SizedBox.shrink();
      }),
    );
  }
}
```

### Method 2: Using `GridView`

Using `GridView` is more flexible and is often preferred when you want dynamic layout behavior.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: Text('Limit Items Per Row'),
        ),
        body: LimitedItemsPerGridView(),
      ),
    );
  }
}

class LimitedItemsPerGridView extends StatelessWidget {
  final int itemsPerRow = 3; // Number of items per row

  @override
  Widget build(BuildContext context) {
    return GridView.builder(
      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: itemsPerRow,
