  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: Text('Wrap Example'),
        ),
        body: ItemList(),
      ),
    );
  }
}

class ItemList extends StatelessWidget {
  final int itemsPerRow = 3; // Limit the number of items per row

  @override
  Widget build(BuildContext context) {
    return Wrap(
      spacing: 8.0, // space between widgets
      runSpacing: 8.0, // space between rows
      children: List.generate(
        20, // Total number of items
        (index) => Container(
          width: (MediaQuery.of(context).size.width / itemsPerRow) - 16,
          height: 50,
          color: Colors.blue[100 * (index % 9)],
          child: Center(
            child: Text(
              'Item ${index + 1}',
              style: TextStyle(fontSize: 16),
            ),
          ),
        ),
      ),
    );
  }
}
```

